import networkx as nx
import random

def is_3_colorable(G):
    # Simple backtracking to check 3-colorability
    color = {}
    def backtrack(node):
        if node == len(G.nodes()):
            return True
        for c in range(3):
            if all(color.get(neigh, -1) != c for neigh in G.neighbors(node)):
                color[node] = c
                if backtrack(node + 1):
                    return True
                del color[node]
        return False
    return backtrack(0)

def has_min_degree(G, d):
    return all(deg >= d for _, deg in G.degree())

def has_max_degree(G, d):
    return all(deg <= d for _, deg in G.degree())

found = False
random.seed(42)  # for reproducibility
for e in range(11, 18):
    for trial in range(100):  # try 100 random graphs per edge count
        G = nx.gnm_random_graph(9, e, seed=random.randint(1,10000))
        if has_min_degree(G, 2) and has_max_degree(G, 4):
            if not nx.is_bipartite(G) and is_3_colorable(G):
                print(f"Found graph with {e} edges")
                edges = sorted([(u,v) if u<v else (v,u) for u,v in G.edges()])
                print(edges)
                found = True
                break
    if found:
        break
if not found:
    print("Not found in trials")
